import glob
import json
import pandas as pd
import os

def main():
    print("Scanning for experiment results...")
    # Find all JSON files generated by the Slurm array tasks
    files = glob.glob("results_sweep_*.json")
    
    if not files:
        print("No result files found! Make sure your Slurm jobs finished successfully.")
        return

    print(f"Found {len(files)} result files. Parsing data...\n")
    data = []
    
    for file in files:
        try:
            with open(file, 'r') as f:
                content = json.load(f)
                
                # Check if 'dynamic' key exists in case a run failed or saved improperly
                if "dynamic" not in content:
                    print(f"Skipping {file}: Missing 'dynamic' data.")
                    continue
                    
                res = content["dynamic"]
                params = res.get("params", {})
                losses = res.get("losses", [])
                
                data.append({
                    "alpha": params.get("alpha"),
                    "beta": params.get("beta"),
                    "gamma": params.get("gamma"),
                    "delta": params.get("delta"),
                    "utility": round(res.get("utility", 0.0), 4),
                    "final_loss": round(losses[-1], 4) if losses else None,
                    "interference": round(res.get("interference", 0.0), 2),
                    "drift": round(res.get("drift", 0.0), 2),
                    "network_mbs": round(res.get("mbs", 0.0), 2),
                    "source_file": os.path.basename(file)
                })
        except Exception as e:
            print(f"Error parsing {file}: {e}")

    if not data:
        print("No valid data could be extracted.")
        return

    # Convert to DataFrame
    df = pd.DataFrame(data)
    
    # Rank configurations: Highest Utility first, then Lowest Final Loss
    df_ranked = df.sort_values(by=["utility", "final_loss"], ascending=[False, True])
    
    print("================ TOP 5 PARAMETER COMBINATIONS ================")
    
    print(df_ranked.drop(columns=['source_file']).head(5).to_string(index=False))
    print("==============================================================\n")
    
    # Save the full ranked list to a CSV file for detailed analysis
    output_csv = "final_sweep_rankings.csv"
    df_ranked.to_csv(output_csv, index=False)
    print(f"Full ranked results successfully saved to '{output_csv}'.")

if __name__ == "__main__":
    main()